import urllib.request
import time
import json

class APIClientError(Exception):
    pass

class RateLimitError(APIClientError):
    pass

class ServerError(APIClientError):
    pass

class ClientError(APIClientError):
    pass

class ConnectionError(APIClientError):
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        retries = 3
        backoff = 0.5

        while retries > 0:
            try:
                req = urllib.request.urlopen(url, timeout=self.timeout)
                return req.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code == 429:  # Rate limit
                    retries -= 1
                    time.sleep(backoff)
                    backoff *= 2
                elif 500 <= e.code < 600:  # Server error
                    time.sleep(1)
                    retries = 0
                elif 400 <= e.code < 500:  # Client error
                    raise ClientError(f"Client error: {e.code}")
            except urllib.error.URLError:  # Network error
                time.sleep(1)
                retries = 0

        if retries == 0 and 'e' in locals() and e.code == 429:
            raise RateLimitError("Rate limit exceeded")
        elif 'e' in locals() and 500 <= e.code < 600:
            raise ServerError(f"Server error: {e.code}")
        else:
            raise ConnectionError("Connection error")
